import type { NetworkId } from "@mavna/core";

/**
 * The chains CCTP routes from that are not EVM.
 *
 * Kept apart from `chains.ts` because that file is generated by sweeping every
 * chain for the same three contract reads, and these three share nothing with it
 * or with each other: a Solana instruction, a Starknet invoke and a Cosmos
 * message have different addresses, different encodings and different notions of
 * what a transaction even is.
 *
 * Each family's constants are verified by its own script rather than by a
 * generic sweep. For Solana that is `scripts/verify-cctp-solana.mjs`, which
 * re-derives the instruction discriminator and the account order from the
 * program's own on-chain IDL and fails if either has moved.
 */

export type ChainFamily = "solana" | "starknet" | "cosmos";

export interface NonEvmChain {
  /** Circle's own identifier for the chain. NOT a chain id. */
  readonly domain: number;
  readonly name: string;
  readonly family: ChainFamily;
  /** Undefined where no explorer is published. Better than a link that 404s. */
  readonly explorer: string | undefined;
  /** Appended to an explorer link, for chains that select a network that way. */
  readonly explorerQuery: string | undefined;
}

export const NON_EVM_CHAINS: Readonly<Record<NetworkId, Readonly<Record<string, NonEvmChain>>>> = {
  testnet: {
    "solana-devnet": {
      domain: 5,
      name: "Solana Devnet",
      family: "solana",
      explorer: "https://explorer.solana.com",
      explorerQuery: "?cluster=devnet",
    },
    "starknet-sepolia": {
      domain: 25,
      name: "Starknet Sepolia",
      family: "starknet",
      explorer: "https://sepolia.starkscan.co",
      explorerQuery: undefined,
    },
  },
  mainnet: {
    solana: {
      domain: 5,
      name: "Solana",
      family: "solana",
      explorer: "https://explorer.solana.com",
      explorerQuery: undefined,
    },
    starknet: {
      domain: 25,
      name: "Starknet",
      family: "starknet",
      explorer: "https://starkscan.co",
      explorerQuery: undefined,
    },
  },
};

export function nonEvmChainFor(network: NetworkId, chainId: string): NonEvmChain | undefined {
  return NON_EVM_CHAINS[network][chainId];
}

export function nonEvmChainsFor(network: NetworkId): readonly string[] {
  return Object.keys(NON_EVM_CHAINS[network]);
}

/** A transaction's page on an explorer, or an empty string when there is none. */
export function nonEvmExplorerTxUrl(network: NetworkId, chainId: string, hash: string): string {
  const chain = NON_EVM_CHAINS[network][chainId];
  if (chain?.explorer === undefined) return "";
  return `${chain.explorer.replace(/\/$/, "")}/tx/${hash}${chain.explorerQuery ?? ""}`;
}
